function stake(uint256 _amount, address _recipient) public {
    // if override staking, then don't allow stake
    require(!isStakingPaused, "Staking is paused");
    // amount must be non zero
    require(_amount > 0, "Must have valid amount");

    uint256 yieldyTotalSupply = IYieldy(YIELDY_TOKEN).totalSupply();

    // Don't rebase unless tokens are already staked or could get locked out of staking
    if (yieldyTotalSupply > 0) {
        rebase();
    }

    IERC20Upgradeable(STAKING_TOKEN).safeTransferFrom(
        msg.sender,
        address(this),
        _amount
    );

    Claim storage info = warmUpInfo[_recipient];

    // if claim is available then auto claim tokens
    if (_isClaimAvailable(_recipient)) {
        claim(_recipient);
    }

    _depositToTokemak(_amount);

    // skip adding to warmup contract if period is 0
    if (warmUpPeriod == 0) {
        IYieldy(YIELDY_TOKEN).mint(_recipient, _amount);
    } else {
        // create a claim and mint tokens so a user can claim them once warm up has passed
        warmUpInfo[_recipient] = Claim({
            amount: info.amount + _amount,
            credits: info.credits +
                IYieldy(YIELDY_TOKEN).creditsForTokenBalance(_amount),
            expiry: epoch.number + warmUpPeriod
        });

        IYieldy(YIELDY_TOKEN).mint(address(this), _amount);
    }

    sendWithdrawalRequests();
}

function canBatchContractByIndex(uint256 _index)
    external
    view
    returns (address, bool)
{
    return (
        contracts[_index],
        IStaking(contracts[_index]).canBatchTransactions()
    );
}

function removeAddress(address _address) external onlyOwner {
    uint256 contractsLength = contracts.length;
    for (uint256 i; i < contractsLength; ) {
        if (contracts[i] == _address) {
            delete contracts[i];
        }
        unchecked {
            ++i;
        }
    }
}

function canBatchContracts() external view returns (Batch[] memory) {
    uint256 contractsLength = contracts.length;
    Batch[] memory batch = new Batch[](contractsLength);
    for (uint256 i; i < contractsLength; ) {
        bool canBatch = IStaking(contracts[i]).canBatchTransactions();
        batch[i] = Batch(contracts[i], canBatch);
        unchecked {
            ++i;
        }
    }
    return batch;
}

function removeLiquidity(uint256 _amount) external {
    // check balance before removing liquidity
    require(_amount <= balanceOf(msg.sender), "Not enough lr tokens");
    // claim the stakingToken from previous unstakes
    IStaking(stakingContract).claimWithdraw(address(this));

    uint256 amountToWithdraw = _calculateReserveTokenValue(_amount);

    // verify that we have enough stakingTokens
    require(
        IERC20Upgradeable(stakingToken).balanceOf(address(this)) >=
            amountToWithdraw,
        "Not enough funds"
    );

    _burn(msg.sender, _amount);
    IERC20Upgradeable(stakingToken).safeTransfer(
        msg.sender,
        amountToWithdraw
    );
}

function instantUnstake(uint256 _amount, address _recipient)
    external
    onlyStakingContract
{
    require(isReserveEnabled, "Not enabled yet");
    // claim the stakingToken from previous unstakes
    IStaking(stakingContract).claimWithdraw(address(this));

    uint256 amountMinusFee = _amount - ((_amount * fee) / BASIS_POINTS);

    IERC20Upgradeable(rewardToken).safeTransferFrom(
        msg.sender,
        address(this),
        _amount
    );

    IERC20Upgradeable(stakingToken).safeTransfer(
        _recipient,
        amountMinusFee
    );
    unstakeAllRewardTokens();
}

function addLiquidity(uint256 _amount) external {
    require(isReserveEnabled, "Not enabled yet");
    uint256 stakingTokenBalance = IERC20Upgradeable(stakingToken).balanceOf(
        address(this)
    );
    uint256 rewardTokenBalance = IERC20Upgradeable(rewardToken).balanceOf(
        address(this)
    );
    uint256 lrFoxSupply = totalSupply();
    uint256 coolDownAmount = IStaking(stakingContract)
        .coolDownInfo(address(this))
        .amount;
    uint256 totalLockedValue = stakingTokenBalance +
        rewardTokenBalance +
        coolDownAmount;

    uint256 amountToMint = (_amount * lrFoxSupply) / totalLockedValue;
    IERC20Upgradeable(stakingToken).safeTransferFrom(
        msg.sender,
        address(this),
        _amount
    );
    _mint(msg.sender, amountToMint);
}
